function buildNav(lang){const l=(lang||localStorage.getItem("vyronLang")||document.documentElement.lang||"ar").slice(0,2).toLowerCase(),k=NAV_I18N[l]?l:"ar",d=NAV_I18N[k],nav=document.querySelector(".bottom-nav");nav.dir=["ar","he","fa","ur"].includes(k)?"rtl":"ltr";nav.setAttribute("aria-label",d.home);
nav.innerHTML=`<svg width="0" height="0" style="position:absolute" aria-hidden="true"><defs><linearGradient id="silverG" gradientUnits="userSpaceOnUse" x1="0" y1="0" x2="0" y2="24"><stop offset="0" stop-color="#fff"/><stop offset=".5" stop-color="#a3afaa"/><stop offset="1" stop-color="#e3e9e6"/></linearGradient><linearGradient id="greenG" gradientUnits="userSpaceOnUse" x1="0" y1="0" x2="0" y2="24"><stop offset="0" stop-color="#9dffc3"/><stop offset="1" stop-color="#17d65f"/></linearGradient></defs></svg><img class="vn-bg" src="${window.__A["nav/bg"]}" alt="" aria-hidden="true" width="2172" height="530"><i class="vn-glow" aria-hidden="true"></i><img class="vn-sv" src="${window.__A["nav/hexsv"]}" alt="" aria-hidden="true" width="620" height="530"><i class="vn-shine" aria-hidden="true"></i>`+NAV.map(([p,i])=>p==="home"?`<button class="nav-home" data-page="home" aria-label="${d.home}"><span class="hm-rim"></span><span class="hm-ring"></span><span class="hm-face"><span class="ni">${IC[i]}</span><small>${d[p]}</small></span></button>`:`<button class="nav-it" data-page="${p}"><span class="ni">${IC[i]}</span><small>${d[p]}</small></button>`).join("");setActive(current);applyAvatar();}
window.VYRON_setNavLang=()=>{buildNav();vxLabels()};buildNav();document.addEventListener("visibilitychange",()=>{const n=document.querySelector(".bottom-nav");if(n)n.classList.toggle("vn-idle",document.hidden)});
document.querySelector(".bottom-nav").addEventListener("pointerdown",e=>{const h=e.target.closest(".nav-home");if(h){h.classList.remove("shine");void h.offsetWidth;h.classList.add("shine");setTimeout(()=>h.classList.remove("shine"),700);}});
const pageNames={home:"الرئيسية",workout:"التمارين",library:"مكتبة التمارين",schedule:"جدولي التدريبي",history:"سجل الحصص",records:"أرقامي القياسية",favorites:"المفضلة",custom:"تمارين مخصصة",calculators:"الحاسبة",progress:"التقدم",profile:"حسابي",notes:"دفتر الملاحظات",reminders:"التذكيرات",settings:"الإعدادات"};
/* header circles: press feedback + active-screen state (CSS in css/glow.css) */
const HC=".vx-b";
function markHeader(page){const sel=page==="settings"?".vx-g":page==="reminders"?".vx-n":String(page).startsWith("profile")?".vx-av":"";document.querySelectorAll(HC).forEach(b=>b.classList.toggle("hc-on",!!sel&&b.matches(sel)))}
const hcDown=e=>{const b=e.target.closest&&e.target.closest(HC);if(!b)return;clearTimeout(b._hcT);b.classList.add("hc-press")};
const hcUp=()=>document.querySelectorAll(".hc-press").forEach(b=>{clearTimeout(b._hcT);b._hcT=setTimeout(()=>b.classList.remove("hc-press"),320)});
document.addEventListener("pointerdown",hcDown,{passive:true});["pointerup","pointercancel","dragstart","blur"].forEach(ev=>document.addEventListener(ev,hcUp,{passive:true,capture:true}));
document.addEventListener("keydown",e=>{if(e.key==="Enter"||e.key===" ")hcDown(e)});document.addEventListener("keyup",hcUp);

/* ---- premium header: art (no text) + three independent live buttons (ring / icon) + live brand ---- */
function vxHead(top){const A=window.__A,av=window.__vxAv||A["hdr/logo"];
 return `<img class="vx-bg" src="${A["hdr/bg"]}" alt="" aria-hidden="true" width="1200" height="346" decoding="sync"><div class="vx-brand" dir="ltr"><b>VYRON</b><b class="g">FIT</b></div>`+
 `<button type="button" class="vx-b vx-g" ${top?'id="menuBtn"':'data-page="settings"'} data-vx="settings" aria-label="${t("settings")}"><img class="vx-ic" src="${A["hdr/gear"]}" alt="" decoding="sync"></button>`+
 `<button type="button" class="vx-b vx-n" data-page="reminders" data-vx="alerts" aria-label="${t("alerts")}"><img class="vx-ic" src="${A["hdr/bell"]}" alt="" decoding="sync"><u></u></button>`+
 `<button type="button" class="vx-b vx-av" data-page="profile" data-vx="profile" aria-label="${t("profile")}"><img class="vx-ic" src="${av}" alt="" decoding="sync"><u></u></button>`}
/* ---- header asset warm-up: hold decoded bitmaps so every rebuilt header paints complete on its first frame ---- */
const _vxW=new Map();let _vxAvK="";
function vxReady(){const A=window.__A,av=window.__vxAv||"",list=[A["hdr/bg"],A["hdr/gear"],A["hdr/bell"],A["hdr/logo"],av];if(av!==_vxAvK){if(_vxAvK)_vxW.delete(_vxAvK);_vxAvK=av}const ps=[];for(const s of list){if(!s)continue;let e=_vxW.get(s);if(!e){const im=new Image();e={im,done:false};const fin=()=>{e.done=true};im.src=s;e.p=(im.decode?im.decode():Promise.resolve()).then(fin,fin);_vxW.set(s,e)}if(!e.done)ps.push(e.p)}return ps.length?Promise.race([Promise.all(ps),new Promise(r=>setTimeout(r,700))]):Promise.resolve()}
function vxFill(){const h=document.getElementById("vxTop");if(h&&!h.querySelector(".vx-b"))h.insertAdjacentHTML("afterbegin",vxHead(true))}
function vxLabels(){document.querySelectorAll(".vx-b[data-vx]").forEach(b=>b.setAttribute("aria-label",t(b.dataset.vx)))}
function setActive(page){const _nv=document.querySelector(".bottom-nav");if(_nv)_nv.classList.toggle("home-on",page==="home");document.querySelectorAll(".bottom-nav button").forEach(b=>b.classList.toggle("active",b.dataset.page===page||(b.dataset.page==="profile"&&page.startsWith("profile"))));}
async function home(){
 const rows=(await all("workouts")).sort((a,b)=>(b.date||"").localeCompare(a.date||""));
 const schedule=await all("schedule");
 const now=new Date(),localISO=d=>`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,"0")}-${String(d.getDate()).padStart(2,"0")}`,today=localISO(now),month=today.slice(0,7);
 const dayNames=["الأحد","الإثنين","الثلاثاء","الأربعاء","الخميس","الجمعة","السبت"];
 const todayName=dayNames[now.getDay()];
 const todayPlan=schedule.filter(x=>x.day===todayName);
 const monthRows=rows.filter(x=>(x.date||"").startsWith(month));
 const weekStart=new Date(now);weekStart.setHours(0,0,0,0);weekStart.setDate(now.getDate()-6);
 const weekRows=rows.filter(x=>{const d=new Date((x.date||"")+"T00:00:00");return !Number.isNaN(d.getTime())&&d>=weekStart&&d<=now;});
 const minutes=weekRows.reduce((n,x)=>n+(Number(x.duration)||0),0);
 const totalExercises=weekRows.reduce((n,x)=>n+(Array.isArray(x.exercises)?x.exercises.length:0),0);
 const last=rows[0];
 const achievements=[{icon:"🏅",label:"أول حصة",ok:rows.length>=1},{icon:"⭐",label:"5 حصص",ok:rows.length>=5},{icon:"🏆",label:"10 حصص",ok:rows.length>=10},{icon:"💚",label:"نشاط هذا الأسبوع",ok:weekRows.length>0}];
 const sc=[["calculators","calc","tCalc"],["progress","stats","tStats"],["library","library","tLib"],["schedule","plan","tPlan"],["records","trophy","tRec"],["custom","builder","tBuild"],["favorites","saved","tFav"],["history","log","tLog"],["food","nutrition","tFood",1],["rest","recovery","tRest",1],["move","activity","tMove",1],["timer","timer","tTimer",1]];
 const calories=weekRows.reduce((n,x)=>n+(Number(x.calories)||0),0),sched=new Set(schedule.map(x=>x.day)),goal=sched.size||3,pct=Math.min(100,Math.round(weekRows.length/goal*100));
 const days=Array.from({length:7},(_,i)=>{const d=new Date(weekStart);d.setDate(weekStart.getDate()+i);const r=weekRows.filter(x=>x.date===localISO(d));return {n:r.length,c:r.reduce((a,x)=>a+(Number(x.calories)||0),0)};});
 const cmax=Math.max(1,...days.map(d=>d.c)),spark=days.map((d,i)=>`${(i*100/6).toFixed(1)},${(34-d.c/cmax*30).toFixed(1)}`).join(" ");
 const xp=rows.length*100+rows.reduce((n,x)=>n+(Array.isArray(x.exercises)?x.exercises.length*10:0),0),lvl=Math.floor(xp/1000)+1,cur=xp%1000;
 const dset=new Set(rows.map(x=>x.date));let st=0;const sd=new Date(now);if(!dset.has(localISO(sd)))sd.setDate(sd.getDate()-1);while(dset.has(localISO(sd))){st++;sd.setDate(sd.getDate()-1);}
 const ws=new Date(now);ws.setDate(now.getDate()-now.getDay());
 const W=weekState(schedule,rows),gl=W.goal||3,pc2=Math.min(100,Math.round(W.doneN/gl*100)),hasRem=(await all("reminders")).some(x=>(x.when||"")>=new Date().toISOString().slice(0,16)),strip=W.days.map(d=>`<button class="wd ${d.today?"today":""} ${d.st}" data-page="schedule"><b>${t("days")[d.i]}</b><i>${d.done?"✓":d.planned?IC.dumbbell:""}</i><small>${d.st==="rest"?t("rest"):""}</small></button>`).join("");
 return `<section class="hx"><header class="vx">${vxHead()}</header>
 <div class="hx-art">${HERO}</div><div class="hx-copy"><p>${t("hello")}${(n=>n?` ${escapeHTML(n)}`:"")(loadAthlete().identity.displayName)}</p><h1>${todayPlan.length?escapeHTML(todayPlan[0].name):t("tag")}</h1><small>${todayPlan.length?`${t("days")[now.getDay()]} • ${t("todayReady")}`:t("tag2")}</small><button class="cta" data-action="new-workout">${IC.play} ${t("cta")}</button></div></section>
 ${homeZone({lang:getLang(),lvl,xpCur:cur,xpMax:1000,goalPct:pc2,kcal:calories,kcalGoal:gl*400,basal:basalKcal(),done:W.doneN,goal:gl,minutes,days:W.days,dayNames:t("days"),})}
 ${scheduleStrip({lang:getLang(),days:W.days,dayNames:t("days"),names:Object.fromEntries(W.days.map(d=>[d.i,(schedule.find(x=>x.day===d.ar)||{}).name]))})}
 <div class="hx-two"><section class="box hx-mus"><div class="box-h"><h2>${t("muscles")}</h2></div><div class="mus-fig"><img src="data:image/jpeg;base64," alt="مناطق العضلات"></div><ul class="mus-lg"><li><i class="r"></i>${t("mTarget")}</li><li><i class="n"></i>${t("mNone")}</li></ul><button class="secondary-btn" data-page="history">${IC.chev} ${t("details")}</button></section>
 <section class="box hx-ach"><div class="box-h"><h2>🏆 ${t("ach")}</h2><button class="link" data-page="records">${IC.chev}</button></div><div class="trophy"><img src="data:image/jpeg;base64," alt="الإنجازات"></div><b class="tl">${st>=3?t("a1"):achievements.filter(a=>a.ok).length?t("a2"):t("a3")}</b><small>${st?`${st} ${t("streak")}`:t("streak0")}</small></section></div>
 ${await smartHomeCard()}<section class="dm" dir="${getLang()==="ar"?"rtl":"ltr"}" aria-label="${t("discover")}">
  <div class="dm-hd"><img src="${window.__A["disc/hd"]}" alt="" width="1136" height="240" decoding="async">
   <span class="dm-br" dir="ltr"><b>VYRON</b><b class="g">FIT</b></span>
   <span class="dm-ph" style="font-size:${Math.min(5.2,33/(Array.from(t("discover").replace(/\s*VYRON FIT\s*$/,"")).length*.5)).toFixed(2)}cqw">${t("discover").replace(/\s*VYRON FIT\s*$/,"")}</span></div>
  <div class="dm-grid">${sc.map((x,i)=>`<button class="dm-c" type="button" data-page="${x[0]}" aria-label="${t(x[2])}"><img src="${window.__A["disc/c"+i]}" alt="" width="260" height="318" decoding="async"><strong>${t(x[2])}</strong></button>`).join("")}</div>
  <img class="dm-ft" src="${window.__A["disc/ft"]}" alt="" width="1136" height="113" decoding="async">
 </section>`;
}
async function library(favoritesOnly=false,customOnly=false){let custom=await all("exercises"),fav=JSON.parse(localStorage.getItem("vyronFavorites")||"[]"),list=[...BASE_EXERCISES,...custom];if(favoritesOnly)list=list.filter(x=>fav.includes(x.id));if(customOnly)list=custom;return `<h1 class="page-title">${favoritesOnly?"التمارين المفضلة":customOnly?"تمارين مخصصة":"مكتبة التمارين"}</h1><p class="page-subtitle">ابحث وصنّف التمارين المناسبة لهدفك.</p><input class="search-input" id="exerciseSearch" placeholder="ابحث عن تمرين أو عضلة..."><div class="action-row"><select class="search-input" id="muscleFilter"><option value="">كل العضلات</option>${["الصدر","الظهر","الأكتاف","الذراع","الأرجل","البطن","كارديو"].map(x=>`<option>${x}</option>`).join("")}</select>${!favoritesOnly?`<button class="secondary-btn" data-action="add-exercise">＋ إضافة تمرين</button>`:""}</div><div id="exerciseList" class="item-list" style="margin-top:13px">${list.length?list.map(ex=>exerciseCard(ex,fav)).join(""):`<div class="empty-state">لا توجد تمارين في هذا القسم بعد.</div>`}</div>`;}
function exerciseCard(ex,fav){return `<div class="list-card" data-exercise-card data-muscle="${ex.muscle}"><div><h3>${escapeHTML(ex.name)}</h3><p>${ex.muscle} • ${ex.equipment} • ${ex.type}</p></div><div><button class="small-btn" data-fav="${ex.id}">${fav.includes(ex.id)?"★":"☆"}</button>${ex.custom?` <button class="small-btn" data-remove-ex="${ex.id}">حذف</button>`:""}</div></div>`;}
async function schedulePage(){const s=await all("schedule"),days=["السبت","الأحد","الإثنين","الثلاثاء","الأربعاء","الخميس","الجمعة"];return `<h1 class="page-title">جدولي التدريبي</h1><p class="page-subtitle">نظّم أيام نشاطك، وعدّل خطتك حسب وقتك واحتياجاتك.</p><section class="schedule-overview"><div><span>أيام الأسبوع</span><b>${new Set(s.map(x=>x.day)).size} / 7</b></div><div><span>حصص مخططة</span><b>${s.length}</b></div><div><span>الهدف</span><b>الانتظام</b></div></section><section class="panel content-card"><h2 class="section-heading">إضافة حصة إلى الجدول</h2><form id="scheduleForm" class="form-grid"><div class="field"><label>اليوم</label><select name="day">${days.map(x=>`<option>${x}</option>`).join("")}</select></div><div class="field"><label>اسم الحصة أو النشاط</label><input name="name" required placeholder="مثلاً: تمارين الجزء العلوي أو المشي"></div><button class="primary-btn full">＋ إضافة إلى الجدول</button></form></section><section class="schedule-week">${days.map(day=>{const items=s.filter(x=>x.day===day);return `<article class="schedule-day ${items.length?"has-plan":""}"><div class="schedule-day-head"><b>${day}</b><span>${items.length?`${items.length} حصص`:"راحة / غير مخطط"}</span></div>${items.length?items.map(x=>`<div class="schedule-entry"><span class="schedule-entry-dot"></span><b>${escapeHTML(x.name)}</b><button class="small-btn" data-delete-schedule="${x.id}" aria-label="حذف ${escapeHTML(x.name)}">حذف</button></div>`).join(""):`<p class="schedule-rest">يمكنك ترك هذا اليوم للراحة أو إضافة نشاط خفيف يناسبك.</p>`}</article>`;}).join("")}</section><p class="muted schedule-note">هذا جدول أسبوعي مرن. يمكنك تغيير الأيام أو حذف الحصص في أي وقت، ولا يلزم تعويض الحصة الفائتة بزيادة التدريب في يوم آخر.</p>`;}
async function recordsPage(){const r=await all("records");return `<h1 class="page-title">أرقامي القياسية</h1><p class="page-subtitle">سجّل أفضل أوزانك وتابع تطور القوة.</p><section class="panel content-card"><form id="recordForm" class="form-grid"><div class="field"><label>التمرين</label><input name="exercise" required placeholder="ضغط صدر بالبار"></div><div class="field"><label>أفضل وزن (كغ)</label><input name="weight" type="number" min=".1" step=".5" required></div><div class="field"><label>التاريخ</label><input name="date" type="date" value="${new Date().toISOString().slice(0,10)}" required></div><button class="primary-btn full">حفظ الرقم القياسي</button></form></section><div class="item-list">${r.length?r.sort((a,b)=>b.weight-a.weight).map(x=>`<div class="list-card"><div><h3>${escapeHTML(x.exercise)}</h3><p>${x.date}</p></div><strong class="green">${x.weight} كغ</strong></div>`).join(""):`<div class="empty-state">لا توجد أرقام قياسية مسجلة.</div>`}</div>`;}
async function notesPage(){const n=await all("notes");return `<h1 class="page-title">دفتر الملاحظات</h1><p class="page-subtitle">دوّن ملاحظاتك وأهدافك التدريبية.</p><section class="panel content-card"><form id="noteForm" class="form-grid"><div class="field full"><label>عنوان الملاحظة</label><input name="title" required></div><div class="field full"><label>المحتوى</label><textarea name="body" required></textarea></div><button class="primary-btn full">حفظ الملاحظة</button></form></section><div class="item-list">${n.length?n.map(x=>`<div class="list-card"><div><h3>${escapeHTML(x.title)}</h3><p>${escapeHTML(x.body)}</p></div><button class="small-btn" data-delete-note="${x.id}">حذف</button></div>`).join(""):`<div class="empty-state">لا توجد ملاحظات بعد.</div>`}</div>`;}
async function remindersPage(){const r=await all("reminders");return `<h1 class="page-title">التذكيرات</h1><p class="page-subtitle">أضف مواعيد تساعدك على الالتزام بالتدريب.</p><section class="panel content-card"><form id="reminderForm" class="form-grid"><div class="field"><label>عنوان التذكير</label><input name="title" required placeholder="موعد التدريب"></div><div class="field"><label>التاريخ والوقت</label><input name="when" type="datetime-local" required></div><button class="primary-btn full">إضافة تذكير</button></form></section><div class="item-list">${r.length?r.sort((a,b)=>a.when.localeCompare(b.when)).map(x=>`<div class="list-card"><div><h3>${escapeHTML(x.title)}</h3><p>${x.when.replace("T"," ")}</p></div><button class="small-btn" data-delete-reminder="${x.id}">حذف</button></div>`).join(""):`<div class="empty-state">لا توجد تذكيرات محفوظة.</div>`}</div><p class="muted">التذكيرات محفوظة داخل التطبيق. إشعارات النظام قد تتطلب تثبيت التطبيق ومنح إذن الإشعارات.</p>`;}
async function profilePage(){const p=JSON.parse(localStorage.getItem("vyronProfile")||"{}");return `<h1 class="page-title">حسابي</h1><p class="page-subtitle">ملفك الشخصي وبياناتك الأساسية.</p><section class="panel content-card"><form id="profileForm" class="form-grid"><div class="field"><label>الاسم (اختياري)</label><input name="name" value="${escapeHTML(p.name||"")}"></div><div class="field"><label>العمر</label><input name="age" type="number" min="15" max="100" value="${p.age||""}"></div><div class="field"><label>الطول (سم)</label><input name="height" type="number" min="1" value="${p.height||""}"></div><div class="field"><label>الوزن الحالي (كغ)</label><input name="weight" type="number" step=".1" value="${p.weight||""}"></div><button class="primary-btn full">حفظ الملف الشخصي</button></form></section><section class="panel content-card"><h2>أدوات التطبيق</h2><div class="action-row"><button class="secondary-btn" data-action="notes">دفتر الملاحظات</button><button class="secondary-btn" data-action="reminders">التذكيرات</button><button class="secondary-btn" data-action="settings">الإعدادات والنسخ الاحتياطي</button></div></section>`;}
